#include "core/application/ProviderManager.hpp"
namespace airmuse { ProviderManager::ProviderManager(EventBus&e):events_(e){} Result<void> ProviderManager::Register(std::shared_ptr<IMediaProvider> p){if(!p)return Result<void>::Fail("null provider"); auto id=p->Id(); if(providers_.contains(id))return Result<void>::Fail("duplicate provider: "+id); if(auto r=p->Initialize();!r)return r; subscriptions_.push_back(p->Subscribe([this](const MediaEvent&e){events_.Publish(e);})); providers_.emplace(std::move(id),std::move(p));return Result<void>::Ok();} void ProviderManager::Shutdown(){subscriptions_.clear();for(auto&[_,p]:providers_)p->Shutdown();providers_.clear();} std::shared_ptr<IMediaSession> ProviderManager::FindSession(const ProviderId&p,const SessionId&s)const{auto it=providers_.find(p);if(it==providers_.end())return{};for(auto&session:it->second->GetSessions())if(session->Id()==s)return session;return{};} }
